package com.hbm.machine.rotaryfurnace;
import com.google.gson.*;
import com.hbm.fluid.*;
import com.hbm.item.autogen.ScrapsItem;
import com.hbm.material.*;
import com.hbm.recipe.generic.*;
import com.mojang.logging.LogUtils;
import java.nio.file.*;
import java.util.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Original hbmRotaryFurnace.json inputs/fluid/material-output grammar and first-match source order. */
public final class RotaryFurnaceRecipes {
 private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final Map<String,String> ALIASES=new LinkedHashMap<>();private static final List<String> UNRESOLVED=new ArrayList<>();
 public static void register(){try(var stream=RotaryFurnaceRecipes.class.getResourceAsStream("/hbm/machine-rotary-furnace97-item-aliases.json")){if(stream==null)throw new IllegalStateException("Missing source rotary furnace aliases");JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));}catch(java.io.IOException error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent e)->install(e.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent e)->{var server=e.getPlayerList().getServer();if(e.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<RotaryFurnaceRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(RotaryFurnaceContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}public static List<String> unresolved(){return List.copyOf(UNRESOLVED);}
    public static void reload(MinecraftServer server) { install(server); }
 private static void install(MinecraftServer server){var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var additions=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();UNRESOLVED.clear();Path dir=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=dir.resolve("hbmRotaryFurnace.json");try{Files.createDirectories(dir);boolean custom=Files.isRegularFile(active);JsonObject root;if(custom){merged.values().removeIf(h->h.value().getType()==RotaryFurnaceContent.TYPE.get());try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}}else try(var stream=RotaryFurnaceRecipes.class.getResourceAsStream("/hbm/machine-rotary-furnace97-source-recipes.json")){if(stream==null)throw new IllegalStateException("Missing source rotary furnace recipes");root=JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}var template=new JsonObject();var exported=new JsonArray();template.add("recipes",exported);int order=0;for(var value:root.getAsJsonArray("recipes")){int index=order++;try{var row=value.getAsJsonObject();var ingredients=new ArrayList<GenericIngredient>();for(var input:row.getAsJsonArray("inputs")){var ingredient=GenericRecipeConfigCodec.readIngredient(input.getAsJsonArray(),ALIASES,server.registryAccess());if(ingredient.examples().isEmpty())throw new IllegalArgumentException("Actual input is not registered: "+input);ingredients.add(ingredient);}var inputFluids=new ArrayList<FluidStack>();if(row.has("fluid")){var fluid=row.getAsJsonArray("fluid");var type=HbmFluids.fromName(fluid.get(0).getAsString());if(type==HbmFluids.NONE&&!fluid.get(0).getAsString().equals("NONE"))throw new IllegalArgumentException("Unregistered source fluid "+fluid);inputFluids.add(new FluidStack(type,fluid.get(1).getAsInt(),fluid.size()>2?fluid.get(2).getAsInt():0));}var out=row.getAsJsonArray("output");var material=HbmMaterials.byName(out.get(0).getAsString());if(material==null)throw new IllegalArgumentException("Unregistered source foundry material "+out.get(0));var molten=new MaterialStack(material,out.get(1).getAsInt());var icon=ScrapsItem.create(molten,true);var data=new GenericRecipeData("rotary_"+index,row.get("duration").getAsInt(),0,ingredients,inputFluids,List.of(new GenericOutput(icon)),List.of(),List.of(),"",icon.copy(),false,"",index);var recipe=new RotaryFurnaceRecipe(data,molten,row.get("steam").getAsInt());var id=ResourceLocation.fromNamespaceAndPath("hbm","rotary_furnace/"+(custom?"config/":"default/")+index);additions.put(id,new RecipeHolder<>(id,recipe));var generic=GenericRecipeConfigCodec.write(data,server.registryAccess());var export=new JsonObject();export.add("inputs",generic.has("inputItem")?generic.getAsJsonArray("inputItem"):new JsonArray());if(row.has("fluid"))export.add("fluid",row.get("fluid").deepCopy());export.add("output",out.deepCopy());export.addProperty("duration",recipe.duration());export.addProperty("steam",recipe.steam());exported.add(export);}catch(Exception error){UNRESOLVED.add("row "+index+": "+error.getMessage());}}if(!custom)Files.writeString(dir.resolve("_hbmRotaryFurnace.json"),new GsonBuilder().setPrettyPrinting().create().toJson(template)+"\n");}catch(Exception error){LogUtils.getLogger().error("Cannot load original rotary furnace recipes",error);}additions.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,additions);for(var error:UNRESOLVED)LogUtils.getLogger().warn("Unbound source rotary furnace recipe: {}",error);}
 private RotaryFurnaceRecipes(){}
}
